/* Runs the machine on fake hardware and prints every log line.
 * Usage: build/sim [--trace out.sgt] <run_ms> [EVENT ...]
 * The listed events are sent at t = 0, in order. --trace writes every
 * transition for stategate-view to replay. */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "gen/fake.h"
#include "gen/hal.h"
#include "gen/machine.h"
#include "gen/trace.h"

static device_probe_t probe;

int main(int argc, char **argv) {
    const char *trace_path = NULL;
    if (argc > 2 && !strcmp(argv[1], "--trace")) {
        trace_path = argv[2];
        argc -= 2;
        argv += 2;
    }
    uint64_t run_ms = argc > 1 ? strtoull(argv[1], NULL, 10) : 15000;
    device_safe_hal_t hal = device_safe_hal(device_fake_hal(&probe));
    device_machine_t m;
    device_start(&m, &hal);
    for (int i = 2; i < argc; i++) {
        device_event_t e;
        if (device_event_from_name(argv[i], &e)) device_send(&m, e, &hal);
        else fprintf(stderr, "unknown event %s\n", argv[i]);
    }
    int printed = 0;
    for (uint64_t t = 0; t <= run_ms; t += 10) {
        probe.now_ms = t;
        device_tick(&m, &hal);
        for (; printed < probe.n_logs; printed++)
            printf("%7.1fs  %s\n", (double)probe.logs[printed].at / 1000.0, probe.logs[printed].msg);
    }
    printf("final state: %s\n", device_state_id(m.state));
    if (trace_path) {
        FILE *f = fopen(trace_path, "wb");
        if (!f) {
            perror(trace_path);
            return 1;
        }
        uint8_t buf[128];
        fwrite(buf, 1, device_trace_header(buf), f);
        for (int i = 0; i < probe.n_traces; i++) {
            sg_trace_record(buf, (uint32_t)probe.traces[i].at, (uint16_t)i, 0, 0, probe.traces[i].from, probe.traces[i].event,
                            probe.traces[i].to);
            fwrite(buf, 1, SG_TRACE_RECORD_SIZE, f);
        }
        fclose(f);
        printf("trace: %d transitions written to %s\n", probe.n_traces, trace_path);
    }
    return 0;
}
